defmodule DdDataStreams.SketchTest do
  use ExUnit.Case, async: true

  alias DdDataStreams.Sketch

  # The expected bytes were produced by Datadog's sketches-go (commit
  # 228b76a8e69df016726ce47579da54cffb0d0779) from a sketch built with
  # mapping.NewLogarithmicMappingWithGamma(1.015625, 1.8761281912861705) - the
  # mapping dd-trace-go and dd-trace-java emit, with dense stores - and then
  # marshalled with google.golang.org/protobuf/proto.Marshal. A positive value v
  # is counted in bin floor(ln(v) x 64.49870798963154 + 1.8761281912861705); a
  # negative value is counted in the negative store at the bin of its magnitude.

  defp encoded(values) do
    Enum.reduce(values, Sketch.new(), &Sketch.add(&2, &1)) |> Sketch.to_proto()
  end

  defp hex(encoded), do: Base.decode16!(encoded, case: :mixed)

  test "new/0 uses the tracers' mapping with empty stores" do
    assert Sketch.new() == %Sketch{positive: %{}, negative: %{}, zero_count: 0.0}
  end

  test "an empty distribution carries the mapping and two empty stores" do
    # The mapping message is 18 bytes: gamma as fixed64 (tag 0x09) and the
    # index offset as fixed64 (tag 0x11), 0x3ff0400000000000 and
    # 0x3ffe049efe8ad800. Both stores (fields 2 and 3) are present but empty.
    assert encoded([]) ==
             hex("0a1209000000000040f03f1100d88afe9e04fe3f12001a00")
  end

  test "a positive value lands in the bin its logarithm falls in" do
    # ln(5) x 64.49870798963154 + 1.8761281912861705 = 105.682 -> 105, so the
    # store starts at bin 105 and holds one count: offset field 0x18,
    # zigzag(105) = 210 = 0xd2 0x01.
    assert encoded([5]) ==
             hex("0a1209000000000040f03f1100d88afe9e04fe3f120d1208000000000000f03f18d2011a00")
  end

  test "bins between the lowest and highest occupied bin are written as zeros" do
    # index(1) = 1.876 -> 1 and index(5) = 105.682 -> 105, so the store holds
    # 105 counts from bin 1: 1, then 103 zeros, then 1. zigzag(1) = 2.
    assert encoded([1, 5]) ==
             hex(
               ""
             )
  end

  test "a store starting at bin zero omits the offset field" do
    # ln(0.98) x 64.49870798963154 + 1.8761281912861705 = 0.573 -> 0. Because
    # the lowest occupied bin is 0 there is no 0x18 offset field.
    assert encoded([0.98]) ==
             hex("0a1209000000000040f03f1100d88afe9e04fe3f120a1208000000000000f03f1a00")
  end

  test "bins between occupied bins are written as zeros" do
    # index(2) = 46.583 -> 46 and index(5) = 105, so the store starts at bin 46
    # and holds 60 counts: 1, then 58 zeros, then 1. zigzag(46) = 92 = 0x5c.
    assert encoded([5, 2]) ==
             hex(
               ""
             )
  end

  test "repeated values accumulate in one bin" do
    # Same bins as {5,2}; the count for bin 105 is 2.0 instead of 1.0.
    assert encoded([5, 5, 2]) ==
             hex(
               ""
             )
  end

  test "zero is counted outside both stores" do
    # Nothing is indexable, so both stores are empty and the zero count is 1.0,
    # written as a fixed64 (tag 0x21) rather than a varint.
    assert encoded([0]) ==
             hex("0a1209000000000040f03f1100d88afe9e04fe3f12001a0021000000000000f03f")
  end

  test "negative values are counted in their own store by magnitude" do
    # Positive store: bin 1 only (index(1) = 1.876 -> 1), offset 0x18 0x02.
    # Negative store: bin 46 only, the bin that the magnitude 2 maps to, offset
    # 0x18 0x5c. Zero count 1.0.
    assert encoded([0, 1, -2]) ==
             hex(
               "0a1209000000000040f03f1100d88afe9e04fe3f120c1208000000000000f03f18021a0c1208000000000000f03f185c21000000000000f03f"
             )
  end

  test "values below one map to negative bin indexes" do
    # ln(0.001) x 64.49870798963154 + 1.8761281912861705 = -443.665 -> floor
    # -444, ln(0.002) x 64.49870798963154 + 1.8761281912861705 = -398.958 ->
    # floor -399, so the store holds 46 counts from bin -444.
    # zigzag(-444) = 887 = 0xf7 0x06.
    assert encoded([0.001, 0.002]) ==
             hex(
               ""
             )
  end

  test "payload-sized values map to positive bin indexes" do
    # ln(1024) x 64.49870798963154 + 1.8761281912861705 = 448.947 -> 448,
    # ln(2048) x 64.49870798963154 + 1.8761281912861705 = 493.654 -> 493, so
    # the store holds 46 counts from bin 448. zigzag(448) = 896 = 0x80 0x07.
    assert encoded([1024, 2048]) ==
             hex(
               ""
             )
  end
end
